def test_thread_safety():
    # Use a very slow rate so no meaningful refill happens during the test
    bucket = TokenBucket(rate=0.001, capacity=100)
    results = []

    def worker():
        count = 0
        for _ in range(200):
            if bucket.consume(1):
                count += 1
        results.append(count)

    threads = [threading.Thread(target=worker) for _ in range(4)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert sum(results) == 100  # exactly capacity worth of tokens

def test_invalid_args():
    try:
        TokenBucket(rate=0, capacity=10)
        assert False, "expected ValueError"
    except ValueError:
        pass
    try:
        TokenBucket(rate=10, capacity=0)
        assert False, "expected ValueError"
    except ValueError:
        pass
    bucket = TokenBucket(rate=1, capacity=1)
